// And groups predicates with the AND operator between them.
func And(predicates ...predicate.GithubRepoSync) predicate.GithubRepoSync {
	return predicate.GithubRepoSync(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.GithubRepoSync) predicate.GithubRepoSync {
	return predicate.GithubRepoSync(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.GithubRepoSync) predicate.GithubRepoSync {
	return predicate.GithubRepoSync(sql.NotPredicates(p))
}
